mapper.select:
SELECT id, tenant_id, biz_domain_id, type_key, type_value, name, description, sort_order,
       created_by, updated_by, deleted_by, created_at, updated_at, deleted_at, delete_flag
FROM type_definition
WHERE tenant_id = #{tenantId}
  AND type_key = #{typeKey}
  AND type_value = #{typeValue}
  AND delete_flag = 0
ORDER BY biz_domain_id NULLS FIRST, id ASC
LIMIT 1
